(window.RYADOM_I18N = window.RYADOM_I18N || {})["zh"] = {"strings":{"Разделы":"栏目","Сегодня":"今天","Мой дневник":"我的日记","Места":"地点","Игры":"游戏","Практики":"练习","Обо мне":"关于我","Ты можешь идти в своём темпе.":"你可以按自己的节奏来。","Здесь нет правильных ответов и обязательных серий дней.":"这里没有标准答案，也不用连续打卡。","Пространство для себя":"属于你的空间","Профиль":"个人资料","Как ты сегодня?":"你今天怎么样？","Можно честно. Начнём с того, что есть сейчас.":"可以说实话。我们从此刻的感受开始。","С чего начать":"从哪里开始","Поговорить":"聊聊","Своими словами, без правил":"用你自己的话，没有规则","Потренировать разговор":"练习一次对话","Начальник, мама, отказ, извинение":"上司、妈妈、拒绝、道歉","Подобрать практику":"挑一个练习","Подходящую сейчас":"适合现在的","Рядом":"Ryadom","На твоей стороне":"站在你这边","Напиши, что происходит…":"写下正在发生的事…","Написать сообщение":"写消息","Продиктовать сообщение":"语音输入消息","Отправить":"发送","Озвучивать ответы":"朗读回复","На сегодня":"今天","Достаточно одного маленького шага":"一小步就够了","Не нужно исправлять весь день целиком.":"不必修好一整天。","Твоё пространство":"你的空间","Разговоры и отметки сохраняются только на этом устройстве.":"对话和记录只保存在这台设备上。","Последняя отметка":"最近一次记录","Пока нет":"暂无","Открыть дневник →":"打开日记 →","✦ ПРАКТИКА ДНЯ":"✦ 今日练习","После трудного разговора":"一次艰难的谈话之后","4–6 минут · пройти →":"4–6 分钟 · 开始 →","Только о тебе и твоём состоянии":"只关于你和你的状态","Разговоры, ощущения и места, в которых прошёл твой день. Игровые истории хранятся отдельно.":"构成你这一天的对话、感受和地点。游戏故事单独保存。","Календарь дня ↓":"日历 ↓","7 дней":"7 天","30 дней":"30 天","Как сегодня внутри?":"今天内心感觉如何？","Четыре отдельные отметки от 0 до 4. Это твои ощущения, а не медицинская оценка.":"四项单独评分，从 0 到 4。这是你的感受，不是医学评估。","Тревога":"焦虑","совсем нет":"完全没有","очень сильно":"非常强","Грусть":"悲伤","Беспокойство":"不安宁","Спокойствие":"平静","Что запомнилось сегодня?":"今天有什么让你印象深刻？","(необязательно)":"（可选）","Можно отмечать раз в день. Сегодняшнюю отметку можно изменить.":"每天可以记录一次。今天的记录可以修改。","Сохранить отметку":"保存记录","Сильная тревога":"强烈焦虑","Нет отметок":"没有记录","Сильная грусть":"强烈悲伤","Много спокойствия":"非常平静","Как менялось состояние":"状态的变化","Каждая точка — твоя отметка за день. Пропуски не считаются нулём.":"每个点是你一天的记录。没记录的日子不算作零。","Пока нет точек на графике. Поставь первую отметку выше.":"图表上还没有点。先在上面做第一次记录吧。","0 — совсем нет":"0 — 完全没有","4 — очень сильно":"4 — 非常强","Что можно заметить":"可以注意到的","После трёх отметок здесь появится короткое наблюдение. Пропущенные дни не учитываются.":"记录三次后，这里会出现一句简短的观察。没记录的日子不计算。","Что помогает именно тебе":"真正对你有帮助的","Когда ты попробуешь практику и оценишь её, здесь появятся твои наблюдения.":"当你试过一个练习并打分后，你的观察会出现在这里。","Стереть дневник":"清空日记","Календарь дня":"日历","Предыдущий месяц":"上个月","Следующий месяц":"下个月","Пн":"一","Вт":"二","Ср":"三","Чт":"四","Пт":"五","Сб":"六","Вс":"日","Синяя точка — разговор, зелёная — место. Цвет дня — настроение; другие точки — отметка ощущений. Игровые события сюда не попадают.":"蓝点＝对话，绿点＝地点。日期颜色＝心情；其他点＝感受记录。游戏事件不会出现在这里。","Пока нет записей за этот день. Можно добавить место, которое тебе запомнилось.":"这一天还没有记录。可以添加一个你记得的地方。","Места этого дня":"当天的地点","Пока пусто":"暂时为空","Добавь посещённое место. Приложение не отслеживает перемещения автоматически.":"添加去过的地方。应用不会自动追踪你的行踪。","＋ Добавить место":"＋ 添加地点","Места записываешь только ты. Они остаются на этом устройстве и не привязаны к игровому прогрессу.":"地点只由你自己记录。它们留在这台设备上，与游戏进度无关。","Дневник хранится только на этом устройстве. Посещённые места добавляешь только ты; автоматического отслеживания перемещений нет.":"日记只保存在这台设备上。去过的地方只由你自己添加，不会自动追踪位置。","Место для этого момента":"适合此刻的地方","Куда под настроение?":"按心情去哪里？","Иногда помогает сменить обстановку. Выбери, чего хочется сейчас, и посмотри места поблизости.":"有时换个环境会有帮助。选择你现在想要的，看看附近的地方。","Какое настроение?":"什么心情？","☁ Грустно":"☁难过","◌ Тревожно":"◌焦虑","♡ Романтично":"♡浪漫","✷ Весело":"✷开心","✿ Спокойно":"✿平静","◇ Хочется нового":"◇想要新鲜感","☕ Устало":"☕疲惫","↗ Хочется общения":"↗想和人交流","Можно выбрать настроение, а потом указать город или разрешить определить примерное местоположение.":"先选心情，再输入城市或允许获取大致位置。","Где искать?":"在哪里找？","Геолокация запрашивается только по нажатию и не записывается в дневник. Поиск по названию города показывает места около его центра.":"只有点按时才请求位置，且不会写入日记。按城市搜索会显示市中心附近的地方。","⌖ Рядом со мной":"⌖ 我附近","Или город / район":"或城市／区域","Например, Тбилиси":"例如：杭州","Найти":"搜索","Выбери настроение и место поиска.":"选择心情和搜索位置。","Место найдётся":"总会找到地方","Выбери настроение и нажми «Рядом со мной» или введи город. Любимые места из дневника появятся здесь первыми.":"选好心情后点“我附近”或输入城市。日记里收藏的地方会排在前面。","Порядок: сначала любимые, затем подходящие места по расстоянию. Рейтинги и популярность в соцсетях пока не доступны — мы не подменяем их количеством посещений.":"排序：先是收藏，再按距离列出合适的地方。评分和社交热度暂不可用——我们不会用访问次数冒充。","Моё: что я люблю":"我的：我喜欢的","Работает без интернета. Если поиск мест недоступен, подсказки берутся отсюда и из раздела «Обо мне».":"离线也能用。若搜索不可用，建议来自这里和“关于我”。","Пока пусто. Добавь любимое место, блюдо или занятие: подсказки станут точнее.":"暂时为空。添加喜欢的地方、菜或活动，建议会更准确。","Что добавить":"添加什么","Еда":"美食","Место":"地点","Занятие":"活动","например: кофейня у реки":"例如：河边的咖啡馆","Название или описание":"名称或描述","Добавить":"添加","Новые места: данные участников OpenStreetMap через Photon. Сведения могут быть неполными.":"新地点：OpenStreetMap 贡献者的数据，经由 Photon 提供。信息可能不完整。","Интерактивные истории":"互动故事","Игры про жизнь":"关于生活的游戏","Герои, разговоры и решения, после которых меняется история.":"角色、对话和会改变故事的选择。","Сюжетная игра · одна неделя":"剧情游戏 · 一周","Тихий город: неделя до ответа":"安静小城：答复前的一周（俄语）","Письмо о работе в другом городе, мама, папа, подруга и восемь слотов времени. На всё не хватит — и каждая встреча оставит след.":"一份外地的工作邀约，妈妈、爸爸、一位朋友和八个时间段。时间不够做所有事——每一次见面都会留下痕迹。","Одна неделя, восемь слотов, пять единиц сил":"一周、八个时间段、五点体力","Начать историю →":"开始故事 →","Тренажёры разговоров":"对话练习","Квесты, где выбор слов меняет ход разговора. Опираются на известные методики общения.":"你的措辞会改变对话走向的任务。基于知名的沟通方法。目前仅有俄语版。","КВЕСТ · 6 ШАГОВ · 2 СТИЛЯ":"任务 · 6 步 · 2 种风格","Разговор с начальником":"和上司谈话","Трудная обратная связь. Неудачный ответ оставляет на месте, удачный пускает дальше и называет приём, на котором он держится.":"艰难的反馈。答得不好会停在原地，答得好就能前进，并告诉你背后的技巧。","Тренажёр разговора":"对话练习","КВЕСТ · 5 ШАГОВ · 2 СТИЛЯ":"任务 · 5 步 · 2 种风格","Сказать «нет» коллеге":"对同事说“不”","Отказать на просьбу о выходных так, чтобы не поссориться: пауза, спокойное «нет», держать решение, предложить своё.":"不伤和气地拒绝周末请求：停顿、平静地说“不”、坚持决定、提出你的方案。","Границы на работе":"工作中的边界","Разговор с мамой о границах":"和妈妈谈边界","Сохранить близость и право решать самому: признать чувства, сказать «я», договориться о понятном ритме.":"既保持亲近，又保有自己做决定的权利：承认感受、用“我”来表达、约定清晰的节奏。","Границы в семье":"家庭中的边界","Извиниться и починить":"道歉并修复关系","Подвели близкого человека. Как извиниться конкретно, выслушать и предложить, что исправите.":"你让亲近的人失望了。如何具体地道歉、倾听，并提出如何弥补。","Конфликт и примирение":"冲突与和解","Попросить о помощи":"请求帮助","Попросить так, чтобы человеку было легко и согласиться, и отказать: конкретно, без извинений, с взаимностью.":"请求时让对方答应或拒绝都很容易：具体、不过度道歉、有来有往。","Просьбы":"请求","Разговор о деньгах":"谈钱","Обсудить неравные общие расходы без обвинений: факты, отражение, пропорциональное решение, срок сверки.":"不指责地讨论不均等的共同开支：事实、复述、按比例的方案、约定复盘时间。","Деньги и близкие":"金钱与亲近的人","Сказать, что тебе нужно":"说出你的需要","Попросить больше времени вместе, не обвиняя: мягкий старт, «я»-сообщение, валидация, небольшой эксперимент.":"不指责地请求更多相处时间：温和开场、“我”信息、认可对方、一个小实验。","Отношения":"感情关系","Отказать другу":"拒绝朋友","Отказаться от поездки так, чтобы дружба не пострадала: пауза, тёплое «нет», повтор решения, альтернатива.":"拒绝一次出行而不伤友情：停顿、温暖地说“不”、重复决定、提出替代方案。","Дружба и границы":"友情与边界","Другие сюжетные направления · 12 коротких историй":"其他故事方向 · 12 个短篇（俄语）","Границы без ссоры":"不吵架地设边界","Учиться говорить о своих возможностях и желаниях.":"学会说出自己的能力和意愿。","ИГРАТЬ · 2 ДНЯ":"开始 · 2 天","Тревога и неопределённость":"焦虑与不确定","Отличать риск от тревожных предположений.":"区分真实风险和焦虑的猜测。","ИГРАТЬ · 4 ГЛАВЫ":"开始 · 4 章","Внутренний критик":"内在批评者","Находить более честный и бережный внутренний голос.":"找到更诚实、更温和的内在声音。","Сложный разговор":"一次艰难的对话","Тренировать фразы и слушать ответ собеседника.":"练习说法，并倾听对方的回应。","Когда нет сил":"当没有力气时","Планировать восстановление без гонки продуктивности.":"规划恢复，不搞效率竞赛。","Свои решения":"自己的决定","Замечать чужие ожидания и выбирать свой шаг.":"觉察别人的期待，选择自己的一步。","Отношения с собой":"与自己的关系","Собирать опоры, которые не зависят от оценки других.":"收集不依赖他人评价的支点。","Одиночество и близость":"孤独与亲近","Искать посильные способы установить контакт.":"寻找力所能及的联系方式。","Работа и выгорание":"工作与倦怠","Замечать нагрузку и договариваться о границах.":"觉察负荷，商定边界。","Потеря и перемены":"失去与改变","Давать место чувствам и искать поддержку.":"给感受留出空间，寻找支持。","Тело и забота":"身体与照顾","Замечать сигналы тела без оценивания внешности.":"觉察身体的信号，而不评判外表。","Отделять свои потребности от требований других.":"把自己的需要和别人的要求分开。","Первая история — полноценная, на том же движке, что «Тихий город». Остальные одиннадцать — короткие зарисовки на четыре сцены, их предстоит переписать так же.":"第一个故事是完整的，与《安静小城》使用同一引擎。其余十一个是四个场景的短篇草稿，之后也会同样重写。","Инструменты на каждый день":"每天的小工具","Библиотека практик":"练习库","Выбирай то, что подходит моменту. Можно пропустить любой шаг.":"选择适合此刻的。任何一步都可以跳过。","ПРАКТИКА В ФОКУСЕ · 4–6 МИНУТ":"精选练习 · 4–6 分钟","Когда слова ещё звучат в голове. Сначала найдём опору, затем разберём событие и выберем один посильный шаг.":"当那些话还在脑子里回响时。先找到支撑，再梳理发生了什么，选一个力所能及的步骤。","01 · Опора":"01 · 支撑","02 · Ясность":"02 · 厘清","03 · Действие":"03 · 行动","Попробовать практику →":"试试这个练习 →","Подходит сейчас":"适合现在","Без сравнения":"不比较","Заметь мысль «другие справляются лучше». Замени её на конкретный факт о сегодняшней нагрузке.":"注意“别人都比我应付得好”这个念头，把它换成一个关于今天负荷的具体事实。","Работа":"工作","Рабочая граница":"工作中的界限","Назови реалистичный срок и то, что потребуется, чтобы уложиться. Не обещай невозможного.":"说出一个现实的期限，以及要做到需要什么。不要承诺不可能的事。","Злость":"愤怒","Граница одной фразой":"一句话说出界限","Попробуй фразу: «Мне важно обсудить задачу, когда мы сможем говорить спокойно». Подстрой её под себя.":"试试这句话：“我希望等我们能平静交谈时再讨论这件事。”按你的习惯调整。","Маршруты: несколько шагов подряд":"路线：连续几步","После трудного разговора с начальником":"和上司艰难谈话之后","практика":"练习","Вернуться в момент":"回到当下","Отметить":"标记","После критики":"被批评之后","Факты после встречи":"会后的事实","тренажёр":"练习","Ответ начальнику":"回应上司","Научиться говорить «нет»":"学会说“不”","Пауза перед ответом":"回应前停一停","Право на нет":"说不的权利","Сложный разговор с близким":"和亲近的人的艰难对话","Сначала услышать":"先倾听","Я-сообщение":"“我”信息","Близость и границы":"亲近与边界","Помириться после ссоры":"吵架后和好","Моя часть":"我的那部分","Тёплое сообщение":"一条温暖的消息","Когда совсем нет сил":"完全没有力气的时候","Базовые нужды":"基本需要","Минимальный шаг":"最小的一步","Просьба о помощи":"求助","Тихая прогулка":"安静地散步","Спокойный вечер":"平静的夜晚","Вечерняя граница":"晚上的界限","Выгрузить мысли":"卸下思绪","Переход ко сну":"进入睡眠","Поиск практики":"搜索练习","Например: тревога, начальник, сон…":"例如：焦虑、上司、睡眠…","Все":"全部","Перегрузка":"超负荷","Сон":"睡眠","Нет сил":"没力气","Мысли":"想法","Мягкое дыхание":"温和呼吸","Замедлиться и почувствовать опору.":"放慢下来，感受支撑。","Переключить внимание на то, что вокруг.":"把注意力转到周围。","Слова и границы":"言语与边界","Когда чужие слова задели слишком сильно.":"当别人的话太伤人时。","Разложить по полочкам":"理一理","Отделить событие от мыслей о нём.":"把事件和你对它的想法分开。","Тёплая фраза":"一句温暖的话","Поддержать себя без требования быть сильнее.":"支持自己，而不要求自己更坚强。","Смена обстановки":"换个环境","Вода, движение или немного воздуха.":"喝点水、动一动或透透气。","Три опоры":"三个支点","Оглянись и назови три устойчивых предмета рядом. Почувствуй стопы на полу. Сделай один удобный выдох.":"环顾四周，说出附近三个稳固的物品。感受双脚踩在地上。舒服地呼一口气。","Длинный выдох":"长呼气","Вдохни естественно, затем выдохни немного медленнее. Повтори несколько раз без задержки дыхания и без усилия.":"自然地吸气，再稍微慢一点呼气。重复几次，不要憋气，也不要用力。","Проверка фактов":"核对事实","Запиши: что я знаю точно, что предполагаю и что могу уточнить. Не требуй от себя немедленного решения.":"写下来：我确定知道什么、我在假设什么、我可以去核实什么。别逼自己马上做决定。","План на ближайший час":"接下来一小时的计划","Выбери одно безопасное и выполнимое действие на ближайший час. Остальное пока оставь на потом.":"为接下来一小时选一个安全、做得到的行动，其余的先放一放。","Найди цвет":"找一种颜色","Выбери цвет и найди вокруг пять предметов этого цвета. Верни внимание к комнате, когда мысли ускоряются.":"选一种颜色，在周围找五样这个颜色的东西。思绪加速时，把注意力带回房间。","Контакт с поверхностью":"与支撑面接触","Заметь, как кресло или пол поддерживают тело. Опиши про себя три точки контакта.":"注意椅子或地面如何承托你的身体。在心里描述三个接触点。","Язык":"语言","Язык интерфейса, практик и разговора. Квесты и сюжетные игры пока на русском.":"界面、练习和对话的语言。任务和剧情游戏目前只有俄语。","Только то, что рассказано тобой":"只有你说过的内容","Что обо мне известно":"关于我的信息","Чтобы «Рядом» мог подсказать, куда сходить, что поесть и что поможет, ему нужно знать тебя. Здесь видно всё, что он помнит. Записи остаются только на этом устройстве: любую можно удалить.":"为了让 Ryadom 推荐去哪儿、吃什么、什么对你有帮助，它需要了解你。它记住的一切都在这里。记录只保存在这台设备上，任何一条都可以删除。","Использовать в разговоре и подсказках":"在对话和建议中使用","Подтянуть из любимых мест":"从收藏的地点导入","Что люблю есть":"我爱吃的","блюда, кухня, вкусы":"菜品、菜系、口味","например: тёплый суп, кофе с булочкой":"例如：热汤、咖啡配面包","Где мне хорошо":"让我感觉舒服的地方","места и обстановка":"地点和氛围","например: набережная, тихая библиотека":"例如：江边、安静的图书馆","Как люблю проводить время":"我喜欢怎么打发时间","занятия и ритм":"活动和节奏","например: долгая прогулка, кино вечером":"例如：长时间散步、晚上看电影","Что помогает, когда тяжело":"难受时什么有帮助","то, что правда работает":"真正有效的","например: горячий чай, музыка в наушниках":"例如：热茶、戴耳机听音乐","С кем мне легко":"和谁在一起让我轻松","люди и формат общения":"人和相处方式","например: с сестрой, один на один":"例如：和姐姐一起、一对一","Чего лучше избегать":"最好避开的","что выматывает или раздражает":"让人疲惫或烦躁的","например: шумные места, спешка":"例如：吵闹的地方、匆忙","Стереть всё, что обо мне записано":"清除关于我的所有记录","Дневник, места и игровой прогресс — отдельные данные: их очистка здесь не затрагивается.":"日记、地点和游戏进度是独立的数据：这里的清除不影响它们。","Моя активность за 7 дней":"我 7 天内的活动","Считается только на этом устройстве и никуда не отправляется. Помогает понять, чем ты пользуешься.":"只在这台设备上统计，不会发送到任何地方。帮你了解自己用了什么。","Пока нет данных.":"暂无数据。","Скопировать сводку":"复制摘要","Сбросить счётчики":"重置计数","Данные и конфиденциальность":"数据与隐私","Всё, что ты вводишь, остаётся на этом устройстве. Здесь можно посмотреть, что хранится, сохранить копию или удалить всё.":"你输入的一切都留在这台设备上。在这里可以查看存了什么、保存副本或全部删除。","Другие данные приложения":"其他应用数据","Сохранить копию файлом":"保存为文件副本","Скопировать текст":"复制文本","Восстановить из файла":"从文件恢复","Файл с данными":"数据文件","Восстановить из вставленного текста":"从粘贴的文本恢复","Удалить все мои данные":"删除我的全部数据","Как приложение обращается с данными":"应用如何处理数据","Где хранятся.":"存放在哪里。","В памяти браузера или приложения на этом устройстве. Учётных записей и серверной базы нет. Если очистить данные браузера или сменить устройство без копии, записи пропадут.":"存在这台设备的浏览器或应用存储中。没有账号，也没有服务器数据库。如果清除浏览器数据或在没有备份的情况下换设备，记录会丢失。","Что передаётся наружу.":"哪些内容会发到外部。","Поиск мест: текст запроса и, если разрешишь, примерные координаты уходят в сервисы карт OpenStreetMap (Photon, Nominatim). Режим с сервером и ИИ, если он подключён: текст твоих сообщений уходит на сервер и к ИИ-провайдеру, чтобы получить ответ. Голосовой ввод и озвучка используют службы устройства.":"地点搜索：搜索文字以及（经你允许的）大致坐标会发送到 OpenStreetMap 地图服务（Photon、Nominatim）。服务器与 AI 模式（若已连接）：你的消息文字会发送到服务器和 AI 服务商以获得回复。语音输入和朗读使用设备自带的服务。","Что приложение не делает.":"应用不会做的事。","Не следит за перемещениями, не продаёт и не показывает рекламу, не ставит диагнозов. Счётчики использования считаются только на этом устройстве.":"不追踪行踪、不出售数据、不显示广告、不做诊断。使用统计只保存在这台设备上。","Важно.":"重要。","Приложение не является медицинским изделием и не заменяет помощь специалиста. Это прототип, и тексты ещё не проверены психологом.":"本应用不是医疗器械，不能替代专业帮助。它是原型，文字尚未经过心理学家审阅。","Показать вводную ещё раз":"再次显示介绍","Если сейчас очень тяжело или есть риск навредить себе, позвони по номеру 112 или обратись к близкому человеку.":"如果现在非常难受，或有伤害自己的风险，请拨打当地急救电话或联系身边的人。","Дневник":"日记","Закрыть":"关闭","Маленький шаг":"一小步","Практика после трудного разговора":"艰难谈话后的练习","Прежде чем начать":"开始之前","Коротко о том, как устроено «Рядом».":"简单介绍 Ryadom 如何运作。","Что это":"这是什么","Цифровой помощник для разговора о состоянии, тренировки трудных разговоров и подбора мест. Это не врач и не психолог, диагнозов не ставит и не заменяет специалиста.":"一个数字助手：聊聊你的状态、练习艰难对话、找地方。它不是医生或心理咨询师，不做诊断，也不能替代专业人士。","Где данные":"数据在哪里","Дневник, разговоры и «Обо мне» хранятся только на этом устройстве. Ты можешь выгрузить их или удалить всё в разделе «Обо мне».":"日记、对话和“关于我”只保存在这台设备上。你可以在“关于我”里导出或全部删除。","Что уходит наружу":"哪些会发到外部","Поиск мест отправляет запрос карте (OpenStreetMap). Если подключён режим с сервером и ИИ, текст сообщения уходит на сервер для ответа. Голосовой ввод использует службы твоего устройства.":"地点搜索会把你的查询发送给地图服务（OpenStreetMap）。若连接了服务器与 AI 模式，消息文字会发到服务器以获得回复。语音输入使用你设备的服务。","Если тяжело всерьёз":"如果真的很难受","При мыслях о вреде себе или другим обратись к человеку рядом или по номеру 112. Приложение подскажет, но срочную помощь оно не заменит.":"如果你有伤害自己或他人的念头，请联系身边的人或拨打当地急救电话。应用可以指引方向，但不能替代紧急帮助。","Понятно, продолжить":"明白了，继续","Рядом — маленькие шаги к себе":"Ryadom — 走向自己的一小步","Тревожно":"焦虑","Сегодняшняя отметка сохранена. Её можно изменить.":"今天的记录已保存，可以修改。","дней с отметкой 3–4 из 4":"评分为 3–4（满分 4）的天数","Добавить в любимые":"加入收藏","Любимое место":"收藏的地点","Изменить":"编辑","Удалить":"删除","Разговоры за этот день":"这一天的对话","Удалить разговоры за этот день":"删除这一天的对话","Из «Обо мне»:":"来自“关于我”：","добавлено мной":"我添加的","из разговора":"来自对话","Отметки состояния":"状态记录","Отметка о вводном экране":"已看过介绍页","Разговоры":"对话","Дневник настроения":"心情日记","Посещённые места":"去过的地方","Профиль «Обо мне»":"“关于我”资料","Меньше новостей":"少看新闻","Если поток новостей усиливает тревогу, отложи его на 15 минут и выбери конкретное время для проверки.":"如果新闻让焦虑加重，先放下 15 分钟，再选一个固定时间去看。","Кому можно написать":"可以发消息给谁","Выбери человека, которому можно коротко написать: «Мне тревожно. Можешь побыть на связи?»":"选一个可以简短发消息的人：“我有点焦虑，能陪我聊一会儿吗？”","Назвать чувство":"说出感受","Скажи себе: «Мне сейчас грустно». Не объясняй и не исправляй это чувство в ту же секунду.":"对自己说：“我现在很难过。”不用马上解释或修正这种感受。","Мягкий день":"温和的一天","Составь минимальный план: еда, вода, один обязательный шаг и один посильный источник тепла.":"做一个最简计划：吃饭、喝水、一件必须做的事和一个力所能及的温暖来源。","Память о хорошем":"回想美好","Вспомни один спокойный момент за последнюю неделю. Запиши детали: место, свет, звук.":"回想过去一周里的一个平静时刻，写下细节：地点、光线、声音。","Тёплый контакт":"温暖的联系","Напиши близкому человеку одну честную фразу о своём состоянии, если хочется быть услышанной или услышанным.":"如果想被倾听，给亲近的人写一句关于自己状态的真心话。","Разрешить паузу":"允许自己停一停","Поставь таймер на пять минут. Можно просто посидеть, не превращая отдых в задачу.":"定一个五分钟的计时器。可以只是坐着，不必把休息变成任务。","Небольшая забота":"一点照顾","Выбери одну бережную вещь: плед, душ, чай или прогулку. Отметь, стало ли хоть немного легче.":"选一件温柔的小事：毯子、洗个澡、一杯茶或散散步。留意是否轻松了一点。","Свет и воздух":"光和空气","Если удобно, подойди к окну или выйди на несколько минут. Заметь температуру воздуха и положение тела.":"方便的话，走到窗边或出去几分钟。留意空气的温度和身体的姿势。","Прежде чем отвечать, отойди от переписки на пару минут. Спроси себя, какой результат нужен от ответа.":"回复前先离开聊天几分钟。问问自己，你希望这次回复带来什么结果。","Где злость в теле":"愤怒在身体的哪里","Заметь, где в теле сейчас напряжение. Расслабь челюсть или плечи, если это приятно, не подавляя чувство.":"注意此刻身体哪里紧绷。如果感觉舒服，放松下巴或肩膀，不必压抑情绪。","Черновик без отправки":"不发送的草稿","Напиши резкий ответ в заметке, которую не отправишь. Затем выдели одну просьбу, которую действительно хочешь донести.":"在一条不会发送的笔记里写下尖锐的回复。然后挑出你真正想表达的那一个请求。","Отойти от экрана":"离开屏幕","Положи телефон и сделай несколько шагов. Возвращайся к разговору, когда сможешь выбрать тон.":"放下手机，走几步。等你能选择语气时再回到对话。","Что задело":"是什么刺痛了你","Раздели на две строки: что произошло и какую важную потребность это затронуло.":"分成两行写：发生了什么，它触动了你哪个重要的需要。","Безопасная разрядка":"安全的释放","Сильно прижми стопы к полу на несколько секунд, затем отпусти. Повтори комфортно, без боли.":"双脚用力踩地几秒钟，然后放松。舒适地重复，不要疼痛。","Право отложить":"推迟的权利","Если нет срочности, назначь время ответа позже. Тебе не обязательно решать конфликт в пике эмоций.":"如果不紧急，约一个晚点回复的时间。你不必在情绪最高点解决冲突。","Одна задача":"一件事","Выпиши всё, что давит. Обведи одну задачу, которую можно начать за десять минут.":"写下所有压着你的事。圈出一件十分钟内就能开始的事。","Пять процентов":"百分之五","Спроси: что сделает ближайший час на пять процентов легче? Выбери один маленький шаг.":"问问自己：什么能让接下来一小时轻松百分之五？选一个小步骤。","Снять лишнее":"去掉多余的","Посмотри на список дел и вычеркни, перенеси или попроси помощи хотя бы с одним пунктом.":"看看待办清单，至少划掉、推迟一项，或为它寻求帮助。","Перерыв между делами":"任务间隙的休息","Перед новой задачей сделай паузу: вода, взгляд вдаль, несколько спокойных движений.":"开始新任务前停一下：喝水、望望远处、做几个缓慢的动作。","Проверка тела":"身体检查","Заметь голод, жажду, усталость и напряжение. Начни с самой простой телесной потребности.":"留意饥饿、口渴、疲惫和紧绷。从最简单的身体需要开始。","Достаточно на сегодня":"今天就到这里","Сформулируй критерий «достаточно хорошо» для одной задачи. Остановись, когда он достигнут.":"为一件事定下“足够好”的标准，达到就停。","Попросить ясности":"请求说清楚","Если запрос размытый, уточни срок, приоритет и ожидаемый результат у того, кто его дал.":"如果要求不明确，向提出的人确认期限、优先级和预期结果。","Тихое окно":"安静时段","На десять минут отключи необязательные уведомления и займись одним делом.":"关掉不必要的通知十分钟，只做一件事。","За некоторое время до сна снизь яркость экрана и выбери спокойное занятие без цели «уснуть немедленно».":"睡前一段时间调暗屏幕，选一件安静的事，不以“马上睡着”为目标。","Запиши незавершённые дела и один следующий шаг к каждому. Вернуться к списку можно завтра.":"写下没做完的事，以及每件事的下一步。明天再回到这张清单。","Комфортная поза":"舒适的姿势","Устрой тело удобнее и мягко замечай точки опоры. Дыхание оставь естественным.":"让身体更舒服一些，温和地留意支撑点。呼吸保持自然。","Тихие звуки":"轻柔的声音","Прислушайся к трём звукам вокруг. Не оценивай их, просто отмечай появление и исчезновение.":"聆听周围的三个声音。不评判，只留意它们出现和消失。","Без борьбы со сном":"不跟睡眠较劲","Если не спится, напомни себе: отдых тоже ценен. Выбери спокойное занятие и вернись в постель, когда захочется.":"睡不着时提醒自己：休息本身也有价值。选一件安静的事，想睡时再回到床上。","Назначь момент, после которого рабочие сообщения подождут до завтра, если это возможно.":"如果可能，设定一个时间点，之后的工作消息留到明天。","Мягкое завершение":"温和地收尾","Назови одну вещь, которую удалось сделать сегодня. Даже очень маленькую.":"说出今天做到的一件事，哪怕非常小。","Спокойное утро":"平静的早晨","Подготовь одну мелочь для утра: одежду, стакан воды или список первого дела.":"为早晨准备一件小事：衣服、一杯水，或写下第一件要做的事。","Составь фразу: «Когда произошло…, мне было… Мне хотелось бы…».":"造一个句子：“当……发生时，我感到……我希望……”。","Перескажи своими словами, что было услышано от другого человека, и уточни, верно ли это понято.":"用自己的话复述你从对方那里听到的内容，并确认自己理解得对不对。","Попробуй короткий ответ без длинного оправдания: «Сейчас я не могу. Давай обсудим другой вариант».":"试试简短的回答，不长篇解释：“我现在做不到。我们谈谈别的办法吧。”","Раздели лист: «за что отвечаю я» и «за что отвечает другой». Не бери на себя обе стороны.":"把一张纸分成两栏：“我负责的”和“对方负责的”。不要把两边都揽到自己身上。","Пауза в разговоре":"对话中的暂停","Если разговор накаляется, предложи вернуться к нему в конкретное время после паузы.":"如果对话升温，提议暂停一下，约个具体时间再谈。","Запиши: как я хочу поддерживать контакт и что мне при этом важно решать самостоятельно.":"写下：我想如何保持联系，以及哪些事我想自己决定。","Один вопрос":"一个问题","Вместо догадки спроси: «Что именно ты имеешь в виду?» Дай другому возможность прояснить слова.":"与其猜测，不如问：“你具体是什么意思？”给对方澄清的机会。","Если хочется контакта, отправь простое сообщение без ожидания немедленного ответа.":"如果想联系某人，发一条简单的消息，不必期待马上回复。","После сложного разговора запиши конкретные задачи и договорённости отдельно от тона и эмоций.":"艰难谈话后，把具体任务和约定单独写下来，与语气和情绪分开。","Уточнить приоритет":"确认优先级","Спроси, какое из двух дел важнее сегодня. Это превращает неопределённость в выбор.":"问清楚两件事里今天哪件更重要。这样不确定就变成了选择。","Составь спокойный черновик: факт, уточняющий вопрос и срок, когда вернёшься с ответом.":"写一份平静的草稿：事实、一个澄清问题，以及你何时给出答复。","Раздели обратную связь на полезную часть, спорную часть и форму подачи. Возьми только то, что поможет задаче.":"把反馈分成有用的部分、有争议的部分和表达方式。只留下对任务有帮助的。","Маленькая победа":"一个小胜利","Запиши одно завершённое дело за день. Даже если другие ещё ждут.":"写下今天完成的一件事，即使其他事还在等着。","Переход домой":"切换回家模式","Закрой рабочий день короткой заметкой о первом шаге на завтра. Переключись на другую деятельность.":"用一条关于明天第一步的小便签结束工作日，然后换做别的事。","Найти союзника":"找一个盟友","Подумай, кто может помочь уточнить задачу, дать контекст или поддержать после трудного разговора.":"想想谁能帮你弄清任务、提供背景，或在艰难谈话后支持你。","Вернуться к опоре, отделить событие от мыслей и выбрать свой следующий шаг.":"回到支撑点，把事件和想法分开，选择下一步。","Проверь сон, еду, воду и паузы. Выбери самое доступное сейчас.":"检查睡眠、饮食、喝水和休息。选现在最容易做到的。","Сократи задачу до действия на две минуты. Можно остановиться после него.":"把任务缩小到两分钟就能做的动作。做完可以停下。","Не объяснять усталость":"不必解释疲惫","Скажи себе: «Сил мало, и я могу выбрать посильный темп». Определи один обязательный пункт.":"对自己说：“我力气不多，可以选一个承受得了的节奏。”确定一件必须做的事。","Пауза без экрана":"不看屏幕的休息","На несколько минут убери экран и посмотри вдаль или закрой глаза, если комфортно.":"放下屏幕几分钟，望向远处，舒服的话也可以闭上眼睛。","Сформулируй конкретную небольшую просьбу человеку, который может помочь.":"向能帮忙的人提出一个具体的小请求。","Список «потом»":"“以后再说”清单","Запиши необязательные дела в список на другой день, чтобы не держать их в голове.":"把不着急的事写进另一天的清单，就不用一直记在脑子里。","Если есть силы и безопасно, пройди несколько минут в удобном темпе. Отдых тоже остаётся вариантом.":"如果有力气且安全，以舒适的速度走几分钟。休息也依然是一个选择。","Один приятный момент":"一个愉快的瞬间","Выбери простую вещь, которая не требует подготовки: музыка, вода, окно или тёплый душ.":"选一件不需要准备的简单小事：音乐、一杯水、窗边或热水澡。","Мысль или факт":"想法还是事实","Запиши тревожную мысль и рядом — факты за и против. Оставь место для неизвестного.":"写下令你焦虑的想法，旁边写支持和反对它的事实。给未知留一点空间。","Название мысли":"给想法命名","Когда мысль повторяется, произнеси: «У меня появилась мысль, что…». Это создаёт небольшую дистанцию.":"当一个想法反复出现时，说：“我有一个想法，觉得……”。这会带来一点距离。","Круг влияния":"影响圈","Раздели ситуацию на то, что можешь изменить, на что можешь повлиять и что сейчас вне контроля.":"把情况分成三类：你能改变的、你能影响的、此刻不在你控制范围内的。","Один следующий шаг":"下一步","Вместо полного плана выбери действие, которое можно сделать сегодня.":"不必做完整计划，选一个今天就能做的行动。","Вернуться к ощущениям":"回到感官","Назови три звука, две видимые детали и одно ощущение от поверхности под рукой.":"说出三个声音、两个看得见的细节和手下表面的一种触感。","Время для мысли":"给想法一个时间","Если мысль возвращается, запиши её и назначь короткое время позже, когда сможешь к ней вернуться.":"如果想法又回来了，把它写下来，并约一个稍后的短时间再去想它。","Два объяснения":"两种解释","Найди ещё одно возможное объяснение событию, кроме самого пугающего. Не обязательно верить в него сразу.":"除了最可怕的那个，再为这件事找一个可能的解释。不必马上相信它。","Спросить, а не угадать":"问而不是猜","Если мысль касается намерений другого, сформулируй вопрос, который поможет прояснить ситуацию.":"如果想法关乎别人的意图，就想一个能帮你弄清情况的问题。","Что уже помогает":"已经在帮你的","Заметь, что сейчас поддерживает тебя: человек, место, движение или привычка. Сохрани это в памяти.":"留意此刻支撑你的是什么：一个人、一个地方、运动或一个习惯。记住它。","Поблагодарить себя":"感谢自己","Назови один свой шаг сегодня без оценки его масштаба.":"说出你今天迈出的一步，不评判它有多大。","Фото момента":"此刻的快照","Опиши словами спокойный момент: цвет, звук, температуру и чувство в теле.":"用文字描述一个平静的时刻：颜色、声音、温度和身体的感觉。","Забота на завтра":"给明天的照顾","Выбери одну маленькую вещь, которую хочется повторить завтра.":"选一件明天还想再做的小事。","Делиться хорошим":"分享美好","Если хочется, расскажи кому-то о приятном моменте, не превращая это в отчёт.":"如果愿意，跟别人说说一个愉快的时刻，不必变成汇报。","Просто побыть":"只是待着","Разреши себе несколько минут ничего не улучшать. Замечай, что уже есть.":"允许自己有几分钟什么都不改进，留意已经在的东西。","Мягкий план":"温和的计划","Пока спокойно, запиши, что обычно помогает в более сложные дни.":"趁现在平静，写下在更难的日子里通常对你有帮助的东西。","Свободное время":"自由时间","Оставь в дне небольшой отрезок без обязательного результата.":"在一天中留一小段不需要任何结果的时间。","2 минуты":"2 分钟","Дыши комфортно, без задержки и усилия. На вдохе круг расширяется, на выдохе сужается. Если кружится голова, остановись и дыши обычно.":"舒服地呼吸，不憋气、不用力。吸气时圆圈变大，呼气时变小。如果头晕，就停下来正常呼吸。","Начать дыхание":"开始呼吸","Закончить":"结束","Дыши в своём ритме":"按自己的节奏呼吸","1 минута":"1 分钟","Назови 5 вещей, которые видишь; 4, которые ощущаешь телом; 3 звука. Не спеши. Сейчас ты здесь.":"说出你看到的 5 样东西、身体感觉到的 4 样、3 种声音。不着急。此刻你就在这里。","Представь между собой и резкими словами прозрачное стекло. Слова остаются по ту сторону. Спроси себя: что из сказанного относится к задаче, а что говорит о состоянии другого человека?":"想象你和那些刺耳的话之间隔着一块透明玻璃，话语留在另一边。问问自己：哪些话和任务有关，哪些更多反映了对方的状态？","3 минуты":"3 分钟","Запиши три короткие строки: 1) Что произошло? 2) Что я сейчас чувствую? 3) Какой один небольшой шаг мне доступен? Не нужно искать идеальное решение.":"写三行短句：1）发生了什么？2）我现在有什么感受？3）我能做的一小步是什么？不需要完美的答案。","Если бы близкий человек оказался на твоём месте, какие слова поддержки нашлись бы для него? Попробуй обратиться с этой же фразой к себе.":"如果亲近的人处在你的位置，你会对他说什么支持的话？试着对自己说同样的话。","Если есть возможность, встань, сделай несколько спокойных шагов и выпей воды. Посмотри в окно или выйди на воздух. Потом проверь, изменилось ли что-то хотя бы на один процент.":"如果可以，站起来，平静地走几步，喝点水。看看窗外或出去透透气。然后看看有没有哪怕百分之一的变化。","1 мин":"1 分钟","2 мин":"2 分钟","3 мин":"3 分钟","5 мин":"5 分钟","10 мин":"10 分钟","✦ РЯДОМ · ПРАКТИКА":"✦ RYADOM · 练习","ПЕРЕД НАЧАЛОМ":"开始之前","Что осталось после разговора?":"谈话之后留下了什么？","Нам не нужно сейчас разбирать всё сразу. Отметь, с кем был разговор и насколько сильно он задел тебя в данный момент.":"现在不必一下子理清一切。标出谈话对象，以及此刻它让你多难受。","На работе":"在工作中","С близким":"和亲近的人","В другой ситуации":"在其他情况下","Насколько сильно задело сейчас?":"现在有多难受？","Немного":"有一点","Очень сильно":"非常","Если сейчас небезопасно или ситуация продолжается, сначала позаботься о своей безопасности и обратись к человеку рядом. Практику можно закрыть в любой момент.":"如果此刻不安全，或情况仍在继续，先照顾好自己的安全，联系身边的人。练习随时可以关闭。","Начать →":"开始 →","01 · ВЕРНУТЬСЯ В МОМЕНТ":"01 · 回到当下","Сейчас ты здесь":"此刻你在这里","Не нужно менять дыхание. Найди глазами одну вещь вокруг, услышь один звук и почувствуй опору под ногами или телом. Нажми на то, что удалось заметить.":"不需要改变呼吸。用眼睛找到周围的一样东西，听到一个声音，感受脚下或身下的支撑。点一下你注意到的。","здесь":"此地","и сейчас":"此刻","○ Вижу предмет":"○ 看到一样东西","○ Слышу звук":"○ 听到一个声音","○ Чувствую опору":"○ 感到支撑","Можно просто прочитать и двигаться дальше. Если внимание к телу неприятно, пропусти этот шаг.":"你也可以只是读一读然后继续。如果关注身体让你不舒服，就跳过这一步。","Назад":"返回","Продолжить →":"继续 →","✓ Вижу предмет":"✓ 看到一样东西","✓ Слышу звук":"✓ 听到一个声音","✓ Чувствую опору":"✓ 感到支撑","02 · ОТДЕЛИТЬ СОБЫТИЕ ОТ МЫСЛИ":"02 · 把事件和想法分开","Две разные вещи":"两件不同的事","Попробуй разделить то, что произошло, и то, что подумалось после. Это не проверка правильности твоих чувств. Поля можно оставить пустыми.":"试着把发生的事和之后冒出的想法分开。这不是检验你的感受对不对。可以留空。","Что было сказано или сделано?":"说了什么或做了什么？","Какая мысль у меня об этом появилась?":"我对此冒出了什么想法？","Чувства реальны. Мысль о себе — не всегда факт. Необязательно находить объяснение прямо сейчас.":"感受是真实的。关于自己的想法不一定是事实。不必现在就找到解释。","03 · ОДИН СЛЕДУЮЩИЙ ШАГ":"03 · 下一步","Что сейчас подойдёт?":"现在什么合适？","Выбери действие, которое зависит от тебя. Оно может быть маленьким и не обязано решать весь конфликт.":"选一个取决于你的行动。它可以很小，不必解决整个冲突。","Дать себе паузу":"给自己一个暂停","Можно ничего не отправлять прямо сейчас. Назначь момент, когда снова посмотришь на ситуацию.":"现在不必发送任何东西。定一个时间再来看看这件事。","Уточнить задачу":"确认任务","Этот вариант подходит, если за неприятным тоном была конкретная рабочая задача.":"如果不愉快的语气背后有具体的工作任务，就适合这个选项。","Обозначить границу":"划出界限","Подстрой слова под себя. Ты выбираешь время и безопасный способ разговора.":"按自己的习惯调整措辞。时间和安全的谈话方式由你来选。","Попросить поддержки":"寻求支持","Поддержка может быть короткой: сообщение, звонок или совместная прогулка.":"支持可以很简短：一条消息、一个电话或一起散步。","Как сейчас, по той же шкале?":"现在呢？用同样的尺度打分。","Не хочу оценивать":"不想打分","Завершить и сохранить →":"完成并保存 →","ВОЗМОЖНАЯ ФРАЗА":"可以说的话","«Я вернусь к разговору позже. Сейчас мне нужно немного времени».":"“我稍后再来谈这件事。现在我需要一点时间。”","Готово":"完成","ТВОЙ МАЛЕНЬКИЙ ШАГ":"你的一小步","Можно остановиться здесь":"可以在这里停下","Состояние замечено, действие выбрано. Не нужно заставлять себя чувствовать лучше.":"状态已经被注意到，行动也选好了。不必强迫自己感觉更好。","ЧТО ВЫБРАНО":"选择了什么","Состояние пока не изменилось. Ты всё равно можешь остановиться или выбрать поддержку.":"状态还没有变化。你依然可以停下或选择支持。","В дневник сохранены только тема, выбранный шаг и твоя оценка результата. Написанные тобой фразы не сохранялись.":"日记里只保存了主题、选择的步骤和你的评分。你写的句子没有保存。","Вернуться в приложение":"返回应用","Добавить место":"添加地点","Название *":"名称 *","Например, любимая кофейня":"例如：最喜欢的咖啡馆","Район или адрес":"区域或地址","Необязательно":"可选","Примерное время":"大致时间","Что это за место?":"这是什么地方？","Кафе":"咖啡馆","Парк":"公园","Прогулка":"散步","Культура":"文化","Другое":"其他","Как тебе там было?":"在那里感觉怎么样？","Спокойно":"平静","Радостно":"开心","Уютно":"温馨","Грустно":"难过","По-разному":"复杂","Что запомнилось?":"印象深的是什么？","Отмена":"取消","Сохранить место":"保存地点","Удалить разговоры, отметки, места и любимые места из дневника на этом устройстве? Игровой прогресс останется.":"要从这台设备的日记中删除对话、记录、地点和收藏吗？游戏进度会保留。","{x}: {0}":"{x}：{0}","Сообщений в разговоре":"对话中的消息","Практик открыто":"打开的练习","Тренажёров начато":"开始的练习","Тренажёров пройдено":"完成的练习","Открытий «Практик»":"打开“练习”次数","Открытий «Игр»":"打开“游戏”次数","Открытий «Мест»":"打开“地点”次数","Открытий дневника":"打开日记次数","{x}: {y} {0} из {1}":"{x}：{y} {0}/{1}","тревога":"焦虑","грусть":"悲伤","беспокойство":"不安宁","спокойствие":"平静","Да, удалить":"是，删除","Неспешная прогулка, книга или чашка чая. Выбирай только то, на что есть силы.":"慢慢散步、看本书或喝杯茶。只选你有力气做的。","Место, где можно сменить обстановку. Тишину и отсутствие людей лучше проверить самому.":"可以换换环境的地方。是否安静、人多不多，最好自己确认。","Прогулка, вид на город или уютное место для встречи.":"散步、城市景观或适合见面的温馨地方。","Места, где можно гулять, смотреть кино или быть среди людей.":"可以散步、看电影或置身人群中的地方。","Пространства для неторопливого времени.":"适合慢慢度过时光的空间。","Музей, галерея или книжное место могут дать новую мысль.":"博物馆、画廊或书店也许会带来新的想法。","Поблизости и без большого плана: кофе или короткая прогулка.":"就在附近，不用大计划：一杯咖啡或短暂散步。","Места для встречи. Загруженность и атмосферу уточни перед поездкой.":"适合见面的地方。出发前确认人流和氛围。","Будут удалены дневник, разговоры, «Обо мне», места и прогресс игр на этом устройстве. Вернуть их будет нельзя, если нет копии.":"此设备上的日记、对话、“关于我”、地点和游戏进度将被删除。没有备份就无法恢复。","Да, удалить всё":"是，全部删除","Удалить все записи профиля? Вернуть их будет нельзя.":"删除所有个人资料记录？删除后无法恢复。","Да, стереть":"是，清除","После нескольких отметок здесь появится короткое наблюдение о твоём состоянии.":"记录几次之后，这里会出现关于你状态的简短观察。","Здесь появятся твои отметки после первого разговора.":"第一次对话后，你的记录会出现在这里。","Разговор с «Рядом»":"与 Ryadom 的对话","Например: трудный разговор, прогулка или приятный момент":"例如：一次艰难的谈话、一次散步或一个美好时刻","Интерактивный прототип приложения ежедневной эмоциональной поддержки.":"日常情绪支持应用的交互原型。","Твои мысли остаются только на этом экране и не сохраняются":"你的想法只留在这个屏幕上，不会被保存","Заметка":"备注","Как ты сейчас после этого шага?":"做完这一步，你现在怎么样？","Чуть легче":"轻松了一点","Пока так же":"暂时没变化","Стало хуже":"变糟了","День":"天","Отмечено состояний: {0}. График показывает только твои ответы, без оценок и диагнозов.":"已记录状态：{0}。图表只显示你的回答，没有评价或诊断。","Одна короткая отметка в день — уже начало.":"每天一次简短记录，就已经是开始。","Удалить все отметки из этого браузера?":"删除此浏览器中的所有记录？","В {0} из {1} отмеченных дней тревога была сильной. Можно посмотреть, что происходило в эти дни, и обратиться за поддержкой, если это мешает жить.":"在已记录的 {1} 天中，有 {0} 天焦虑很强。可以看看那些天发生了什么，如果影响生活，可以寻求支持。","За выбранный период сильная тревога отмечалась в {0} из {1} дней. Посмотри, какие занятия и разговоры помогали тебе чувствовать себя спокойнее.":"在所选时间段内，{1} 天中有 {0} 天记录了强烈焦虑。看看哪些活动和对话让你更平静。","На этот день нет записи. Пустая клетка ничего не говорит о том, каким был день.":"这一天没有记录。空白格并不说明这一天过得怎样。","чуть легче":"轻松了一点","без изменений":"没有变化","стало хуже":"变糟了","без оценки":"未评价","Удалить разговоры, отметки и заметки дневника из этого браузера? Игровой прогресс останется.":"删除此浏览器中的对话、记录和日记笔记？游戏进度会保留。","Скоро":"即将推出","Ничего не найдено. Попробуй другое слово или состояние.":"没有找到。试试别的词或状态。","Поддержка":"支持","Мне очень жаль, что сейчас так тяжело. Если есть риск причинить себе вред прямо сейчас, позови человека рядом и обратись за срочной помощью по местному экстренному номеру. Ты можешь сказать: «Мне сейчас небезопасно оставаться одной или одному. Побудь со мной и помоги получить помощь».":"很抱歉你现在这么难受。如果此刻有伤害自己的风险，请叫身边的人，并拨打当地紧急电话求助。你可以说：“我现在一个人待着不安全。请陪着我，帮我获得帮助。”","Показать фразу для близкого":"显示给亲近之人的话","Можно отправить: «Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь со мной. Помоги обратиться за помощью».":"你可以发送：“我现在很难受。请给我打电话或陪着我。帮我寻求帮助。”","Хорошо, что об этом сказано вслух. Если состояние изменится, обратись к человеку рядом или за срочной помощью.":"说出来很好。如果状态有变化，请找身边的人或寻求紧急帮助。","Начнём новый разговор. Как ты сейчас?":"我们开始新的对话吧。你现在怎么样？","Рада это слышать. Что сегодня помогло тебе чувствовать себя так?":"很高兴听到。今天是什么让你有这样的感觉？","Спасибо, что об этом сказано. Что произошло или когда это ощущение появилось? Можно ответить своими словами.":"谢谢你说出来。发生了什么，或者这种感觉是什么时候出现的？可以用你自己的话回答。","Близкие":"亲近的人","Не знаю, почему":"不知道为什么","Понимаю. Насколько сильно это сейчас ощущается — от 1 до 4? Если сложно оценить, можно пропустить.":"明白。现在这种感觉有多强，1 到 4？如果难以评估，可以跳过。","1 · немного":"1 · 一点","2 · заметно":"2 · 明显","3 · сильно":"3 · 强烈","4 · очень сильно":"4 · 非常强烈","Пропустить":"跳过","Что хочется сделать с этим ощущением?":"你想怎样对待这种感觉？","Что сейчас было бы нужнее: немного успокоиться, разобраться в ситуации, просто выговориться или отдохнуть?":"现在更需要什么：稍微平静下来、理清情况、只是倾诉，还是休息？","Успокоиться":"平静下来","Разобраться":"理清楚","Выговориться":"倾诉","Отдохнуть":"休息","Я слушаю. Расскажи, что было самым неприятным или важным в этом моменте.":"我在听。说说那一刻最难受或最重要的是什么。","Похоже, это действительно задело. Что хотелось бы получить сейчас? Можно выбрать маленький шаг, а можно продолжить разговор.":"听起来这真的刺痛了你。你现在想要什么？可以选一个小步骤，也可以继续聊。","Рассказать ещё":"再说说","Закончить пока":"先到这里","Я рядом. Что ещё важно сказать?":"我在。还有什么重要的想说？","Спасибо, что поделилась или поделился. Можно вернуться, когда захочешь.":"谢谢你的分享。想回来随时都可以。","Новый разговор":"新对话","Я слушаю. Что хочется рассказать?":"我在听。你想说些什么？","Спасибо за разговор. Вернись, когда захочешь.":"谢谢你的聊天。想回来随时回来。","Слышу тебя. Что из этого сейчас важнее всего? Можешь рассказать ещё или выбрать шаг.":"我听到了。其中现在最重要的是什么？你可以多说一些，或选一个步骤。","Рада, что стало хоть немного легче. Что именно помогло?":"很高兴你感觉轻松了一点。具体是什么帮到了你？","Жаль, что стало хуже. Остановимся с этой практикой. Сейчас лучше выбрать более мягкую поддержку или обратиться к близкому человеку.":"很遗憾变糟了。我们先停下这个练习。现在最好选择更温和的支持，或联系亲近的人。","Хорошо, что это получилось заметить. Можно попробовать другой шаг или просто остановиться.":"能注意到这一点很好。可以试试别的步骤，或者就此停下。","Расскажу ещё":"我再说说","Я слушаю. Что сейчас на первом плане?":"我在听。现在最让你在意的是什么？","Спасибо за разговор. Береги свой темп.":"谢谢你的聊天。照顾好自己的节奏。","Если захочешь, начнём новый разговор.":"如果你愿意，我们可以开始新的对话。","Тогда начнём с очень маленькой паузы.":"那我们先从一个很小的停顿开始。","Давай отделим то, что произошло, от догадок.":"我们把发生的事和猜测分开。","Можно попробовать один из этих шагов. Выбирай только то, что подходит.":"可以试试其中一个步骤。只选适合你的。","Хочу рассказать ещё":"我想再说说","Пока достаточно":"先这样吧","Как ты после этого шага?":"做完这一步你怎么样？","Голосовой ввод не поддерживается этим браузером":"此浏览器不支持语音输入","Голосовой ввод недоступен в этом браузере. Можно писать текстом.":"此浏览器无法使用语音输入。可以改用文字。","Распознавание голоса выполняет устройство и может передавать запись его сервису. Продолжить?":"语音识别由设备完成，可能会把录音发送给其服务。继续吗？","Да, включить":"是，开启","Остановить запись":"停止录音","Слушаю. Фраза появится в поле ввода — проверь её перед отправкой.":"正在听。文字会出现在输入框里——发送前请检查。","Проверь текст и нажми отправить, когда текст устроит.":"检查文字，满意后点发送。","Нет доступа к микрофону. Можно продолжить текстом.":"无法访问麦克风。可以继续用文字。","Не удалось распознать речь. Попробуй ещё раз или напиши текстом.":"无法识别语音。请再试一次或改用文字。","Не удалось включить микрофон.":"无法开启麦克风。","4–6 минут":"4–6 分钟","Небольшая самостоятельная практика после неприятного разговора.":"一次不愉快的谈话后，可以自己做的小练习。","После трудного разговора · 4–6 минут":"艰难谈话之后 · 4–6 分钟","«Помоги понять: какой результат ожидается и к какому сроку?»":"“帮我理解一下：期望什么结果，什么时候要？”","«Мне важно обсудить вопрос, когда мы можем говорить спокойно».":"“我希望在我们都能冷静交谈时再讨论这个问题。”","«У меня был трудный разговор. Можешь немного побыть со мной на связи?»":"“我刚经历了一次艰难的谈话。你能陪我聊一会儿吗？”","Шаг {0} из 4":"第 {0} 步，共 4 步","Пауза":"暂停","Результат не оценён. Это тоже нормально.":"结果未评价。这也没关系。","Отмечено небольшое облегчение.":"记录到一点点放松。","Стало тяжелее. Эту практику можно оставить и обратиться к человеку, которому доверяешь.":"变得更难受了。可以放下这个练习，去找你信任的人。","Вижу предмет":"我看到一个物体","Слышу звук":"我听到一个声音","Чувствую опору":"我感到有支撑","Например: «Руководитель повысил голос и попросил переделать отчёт»":"例如：“领导提高了嗓门，让我重做报告”","Например: «Наверное, я ни на что не способна или не способен»":"例如：“我大概什么都做不好”","Практика пройдена в твоём темпе. Хочешь рассказать ещё или закончить?":"按你的节奏完成了练习。想再说说，还是结束？","Отмечено, что стало немного легче. Хочешь остановиться или рассказать, какой шаг оказался выбран?":"已记录：轻松了一点。想停下，还是说说你选了哪一步？","Похоже, сейчас стало тяжелее. Остановимся. Можно обратиться к человеку рядом или выбрать другую поддержку.":"看起来更难受了。我们停下吧。可以找身边的人，或选择其他支持。","Спасибо за оценку результата. Хочешь рассказать ещё или закончить?":"谢谢你的评价。想再说说，还是结束？","тревожно":"焦虑","тяжело":"沉重","злюсь":"生气","нормально":"还好","хорошо":"很好","✓ Сделано":"✓ 已完成","Скопировано":"已复制","Не удалось":"失败","Запись о тебе сейчас выключена. Включить её можно в разделе «Обо мне».":"关于你的记录目前已关闭。可以在“关于我”中开启。","Такая запись уже есть или список полон.":"该记录已存在或列表已满。","Избранные места":"收藏的地点","Найденные места":"找到的地点","Выбранный город":"已选城市","Счётчики на этом устройстве":"此设备上的计数","Цепочки практик":"练习链","Согласие на голос":"语音授权","Настройка озвучки":"朗读设置","Прогресс игр":"游戏进度","Прогресс историй":"故事进度","Прогресс квестов":"任务进度","Не удалось прочитать: это не файл данных «Рядом».":"无法读取：这不是 Ryadom 数据文件。","Это не файл данных «Рядом».":"这不是 Ryadom 数据文件。","В файле нет данных для восстановления.":"文件中没有可恢复的数据。","Пока ничего не сохранено":"还没有保存任何内容","Данные для переноса":"迁移数据","Выбери, куда сохранить: «Файлы», облако, почта или мессенджер себе.":"选择保存位置：“文件”、云端、邮箱或发给自己的聊天软件。","Не получилось открыть «Поделиться». Воспользуйся кнопкой «Скопировать текст».":"无法打开“分享”。请使用“复制文本”按钮。","Файл сохраняется. Если ничего не произошло — воспользуйся кнопкой «Скопировать текст».":"正在保存文件。如果没有反应，请使用“复制文本”按钮。","Не получилось сохранить файл. Воспользуйся кнопкой «Скопировать текст».":"无法保存文件。请使用“复制文本”按钮。","Скопировано. Вставь в заметки или сообщение себе.":"已复制。粘贴到备忘录或发给自己的消息里。","Скопировать автоматически не вышло. Текст выделен — скопируй его вручную.":"无法自动复制。文字已选中——请手动复制。","Файл слишком большой.":"文件太大。","Вставь сюда скопированный текст и нажми кнопку ещё раз":"把复制的文字粘贴到这里，再点一次按钮","Всё удалено. Обновляю приложение…":"已全部删除。正在刷新应用…","Где хранятся":"存储位置","Что передаётся наружу":"会向外发送什么","Что приложение не делает":"应用不会做的事","Важно":"重要","Новых мест для добавления нет. Отметь любимые в разделе «Места» или посещения в дневнике.":"没有可添加的新地点。在“地点”中标记收藏，或在日记中标记去过的地方。","Сейчас записи не используются: ни в разговоре, ни в подсказках, ни на сервере.":"目前不会使用这些记录：对话、提示和服务器中都不会。","Романтично":"浪漫","Весело":"开心","Хочется нового":"想要新鲜感","Устало":"累了","Хочется общения":"想和人交流","Расстояние неизвестно":"距离未知","Сад":"花园","Библиотека":"图书馆","Музей":"博物馆","Смотровая площадка":"观景台","Ресторан":"餐厅","Галерея":"画廊","Кинотеатр":"电影院","Театр":"剧院","Достопримечательность":"景点","Арт-пространство":"艺术空间","Книжный магазин":"书店","Бар":"酒吧","Уже есть в твоём дневнике":"已在你的日记中","Отметок об этом месте в дневнике: {0}":"日记中关于此地的记录：{0}","Любимое место · под выбранное настроение может подойти другое":"收藏的地点 · 所选心情下也许别处更合适","На карте ↗":"在地图上 ↗","Была/был здесь":"来过这里","01 / ТВОИ МЕСТА":"01 / 你的地点","Любимые сначала":"收藏优先","02 / ПОБЛИЗОСТИ":"02 / 附近","Новые места рядом":"附近的新地点","Показано {0} мест рядом с «{1}».":"显示“{1}”附近的 {0} 个地点。","Найдено {0} мест в радиусе около 2 км. Данные OpenStreetMap могут быть неполными.":"在约 2 公里范围内找到 {0} 个地点。OpenStreetMap 数据可能不完整。","Поблизости пока не нашлось мест под это настроение. Попробуй другой район или настроение.":"附近暂时没有适合这种心情的地点。试试别的区域或心情。","Поиск новых мест сейчас недоступен. Любимые места из дневника остаются здесь. Попробуй позже или укажи другой район.":"暂时无法搜索新地点。日记中收藏的地点仍在这里。请稍后再试或换个区域。","Этот браузер не поддерживает определение местоположения. Введи город вручную.":"此浏览器不支持定位。请手动输入城市。","Запрашиваем местоположение…":"正在获取位置…","текущей точки":"当前位置","Не удалось получить местоположение. Введи город или район вручную.":"无法获取位置。请手动输入城市或区域。","Не удалось найти этот город или район. Попробуй уточнить название.":"找不到这个城市或区域。试试更准确的名称。","Не удалось найти город сейчас. Попробуй ещё раз позже или используй геолокацию.":"暂时找不到该城市。请稍后再试或使用定位。","Убрать из любимых":"取消收藏","Изменить место":"更改地点","Или выбери любимое:":"或选择一个收藏：","Ты":"你","МЕНЮ":"菜单","Попробовать ещё раз":"再试一次","Дальше →":"下一步 →","Скопировать":"复制","Сначала напиши свою версию.":"先写下你的版本。","Скопировано.":"已复制。","Скопируй текст вручную.":"请手动复制文字。","Запомнить в «Обо мне»":"记到“关于我”","Записано в «Обо мне».":"已记到“关于我”。","К играм":"返回游戏","Озвучка ответов включена":"回复朗读已开启","Озвучка включена.":"朗读已开启。","Данные «Рядом»":"Ryadom 数据","Копия данных приложения «Рядом». Храни её в надёжном месте.":"Ryadom 应用数据的副本。请妥善保存。","Сохранить копию":"保存副本","Как ты сегодня? Можно отметить состояние за минуту.":"今天怎么样？一分钟就能记录状态。","Минутка для себя: как прошёл день?":"给自己一分钟：今天过得怎么样？","Если день был непростым — я рядом. Можно просто отметить настроение.":"如果今天不太容易——我在。可以只记录一下心情。","Напоминания недоступны на этом устройстве.":"此设备不支持提醒。","Напоминание выключено.":"提醒已关闭。","Уведомления запрещены. Их можно разрешить в настройках телефона для приложения «Рядом».":"通知已被禁止。可以在手机设置中为 Ryadom 应用开启。","Напоминание":"提醒","Раз в день мягко напомню отметить состояние. Работает без интернета, ничего никуда не отправляется.":"每天一次温和地提醒你记录状态。无需联网，不会发送任何内容。","Ежедневное напоминание":"每日提醒","Каждый день":"每天","Время напоминания":"提醒时间","Похоже, сейчас тревожно.":"听起来你现在很焦虑。","Похоже, сейчас грустно.":"听起来你现在很难过。","Похоже, сейчас много злости.":"听起来你现在很生气。","Похоже, сил сейчас совсем немного.":"听起来你现在几乎没有力气了。","Похоже, сейчас одиноко.":"听起来你现在很孤单。","Похоже, это задело.":"听起来这刺痛了你。","Похоже, рядом с этим есть чувство вины или стыда.":"听起来这里面还有内疚或羞愧。","Как хорошо это слышать!":"听到这个真好！","Слышу, что это связано с работой.":"我听到这和工作有关。","Слышу, что это связано с семьёй.":"我听到这和家人有关。","Слышу, что это связано с отношениями.":"我听到这和感情关系有关。","Слышу, что это связано с друзьями.":"我听到这和朋友有关。","Слышу, что это связано со здоровьем.":"我听到这和健康有关。","Слышу, что это связано с деньгами.":"我听到这和钱有关。","Слышу, что это связано с учёбой.":"我听到这和学习有关。","Я слушаю. Что было дальше?":"我在听。后来怎么样了？","Это звучит непросто. Что сейчас ощущается сильнее всего?":"听起来不容易。你现在最强烈的感受是什么？","Понимаю. Что для тебя здесь самое важное?":"明白。这里对你来说最重要的是什么？","Спасибо, что рассказываешь. Как это на тебя повлияло?":"谢谢你告诉我。这对你有什么影响？","Если посмотреть на это со стороны — что хотелось бы изменить в первую очередь?":"如果从旁观者的角度看——你最想先改变什么？","Что помогло бы тебе хоть немного прямо сейчас?":"现在什么能让你好受一点点？","Злюсь":"生气","Одиноко":"孤单","Всё хорошо":"一切都好","Куда сегодня сходить?":"今天去哪里？","Просто выговориться":"只是想倾诉","Небольшой шаг, чтобы стало легче":"一个让自己轻松些的小步骤","Потренировать трудный разговор":"练习一次艰难的谈话","Куда сходить или что поесть":"去哪儿或吃什么","Привет. Я — «Рядом». Можно написать, как ты, своими словами или выбрать подсказку.":"你好，我是 Ryadom。你可以用自己的话写下你的感受，或选择一个提示。","На этом языке я понимаю простые фразы. Подсказки-кнопки помогут быть точнее.":"在这种语言中，我能理解简单的句子。提示按钮能让我理解得更准确。","Как хорошо это слышать! Что сегодня порадовало?":"听到这个真好！今天什么让你开心？","Куда сходить отметить?":"去哪里庆祝一下？","Записать в дневник":"写进日记","Есть и сложная часть":"也有难受的部分","Что сейчас было бы полезнее?":"现在什么更有帮助？","Вот что можно попробовать. Любой шаг можно остановить.":"这些可以试试。任何一步都可以随时停下。","Лучше просто поговорим":"还是聊聊吧","Подобрать небольшой шаг":"挑一个小步骤","Продолжу рассказывать":"我继续说","Спасибо за разговор. Я здесь, когда захочется вернуться.":"谢谢你的聊天。想回来的时候我都在。","Начать новый разговор":"开始新对话","Открыть дневник":"打开日记","Похоже, сейчас очень много злости. Если есть риск навредить другому человеку — остановись и выйди из ситуации: на воздух, в другую комнату. Если опасность рядом — звони в экстренную службу.":"听起来你现在非常愤怒。如果有伤害他人的风险——停下来，离开当下的环境：到户外或另一个房间。如果危险就在身边——拨打紧急电话。","То, что ты описываешь, звучит небезопасно. Твоя безопасность важнее всего. Если опасность рядом прямо сейчас — постарайся уйти в безопасное место и позвони в экстренную службу.":"你描述的情况听起来不安全。你的安全最重要。如果危险此刻就在身边——尽量去安全的地方，并拨打紧急电话。","Спасибо, что ты об этом говоришь. Твоя безопасность сейчас важнее всего. С этим не нужно справляться без поддержки: позвони на линию помощи или человеку, которому доверяешь.":"谢谢你说出来。现在你的安全最重要。你不必独自面对：请拨打求助热线，或联系你信任的人。","Показать текст для близкого":"显示给亲近之人的文字","Сейчас я в безопасности":"我现在是安全的","Если опасность прямо сейчас — экстренная служба: 112 (в большинстве стран).":"如果此刻有危险——紧急电话：112（大多数国家适用）。","Линии помощи в других странах: findahelpline.com":"其他国家的求助热线：findahelpline.com","Пожалуйста. Я рядом.":"不客气。我在。","Нет, я не врач и не психолог: не ставлю диагнозов и не лечу. Я помогаю выговориться, назвать, что происходит, и сделать небольшой шаг. Если тяжёлое состояние держится долго или мешает жить, стоит обратиться к специалисту.":"不，我不是医生也不是心理咨询师：不做诊断，也不治疗。我帮你倾诉、说清正在发生什么，并迈出一小步。如果沉重的状态持续很久或影响生活，建议寻求专业人士帮助。","Я «Рядом» — программа, а не человек. Я не врач и не заменяю специалиста.":"我是 Ryadom——一个程序，不是人。我不是医生，也不能替代专业人士。","Хорошо, не будем. Ничего объяснять не нужно. Можно просто побыть рядом или выбрать другое.":"好的，那就不做。什么都不用解释。我们可以就这样待着，或选别的。","Я рядом. Начнём с самого простого: что сейчас ближе?":"我在。我们从最简单的开始：现在哪个最接近你的感受？","Привет. Что сейчас происходит? Можно написать своими словами или выбрать подсказку.":"你好。现在发生了什么？可以用自己的话写，或选择一个提示。","Это стоит запомнить. Хочешь отметить это — сходить куда-нибудь или записать в дневник?":"这值得记住。想纪念一下吗——出去走走，还是写进日记？","А что здесь сильнее всего?":"那其中最强烈的是什么？","Обида":"委屈","Усталость":"疲惫","Хочу понять точнее. Что ближе всего к тому, что сейчас внутри? Можно выбрать подсказку.":"我想理解得更准确。哪个最接近你此刻内心的感受？可以选一个提示。","Из того, что известно о тебе:":"根据我对你的了解：","В разделе «Места» можно выбрать настроение и посмотреть, что рядом.":"在“地点”中可以选择心情，看看附近有什么。","Открыть «Места»":"打开“地点”","Расскажу, что на душе":"我想说说心里话","Расскажи, что ещё происходит.":"说说还发生了什么。","Я слушаю. Можно писать как получается — кусками, без порядка.":"我在听。想到什么写什么——零零碎碎、不按顺序都可以。","Тренажёры трудных разговоров пока доступны только на русском языке. Можно открыть их или выбрать другое.":"艰难对话练习目前只有俄语版本。你可以打开，或选择别的。","Открыть тренажёры":"打开练习","Я слушаю.":"我在听。","Хорошо. Если станет хуже — линии помощи выше, и можно вернуться сюда в любой момент.":"好的。如果变糟了——求助热线就在上面，你也可以随时回到这里。","Можно отправить близкому:":"可以发给亲近的人：","Мне сейчас очень тяжело. Пожалуйста, побудь со мной или позвони мне сейчас. Помоги обратиться за помощью.":"我现在很难受。请陪着我，或现在给我打电话。帮我寻求帮助。","Хорошо, что стало хоть немного легче. Хочешь остановиться на этом или продолжить?":"很好，轻松了一点。想就到这里，还是继续？","Жаль, что стало тяжелее. Давай не продолжать эту практику. Можно связаться с близким человеком или выбрать другой, более мягкий шаг.":"很遗憾变得更难受了。我们不要继续这个练习了。可以联系亲近的人，或选一个更温和的步骤。","Иногда эффект приходит не сразу. Можно попробовать другой способ или просто поговорить.":"有时效果不会马上出现。可以试试别的方法，或者就聊聊。","Другой способ":"换个方法","Подобрано {x}. Можно выбрать любое или ничего.":"已挑选：{x}。可以任选一个，也可以都不选。","по последней отметке «{q}»":"根据你最近的记录“{q}”","по последней отметке «{q}» и позднему времени":"根据你最近的记录“{q}”和较晚的时间","{x} · Открыть →":"{x} · 打开 →","{0} из {1}":"{0} / {1}","Отметить шаг цепочки: {x}":"标记练习链步骤：{x}","Открыть практику: {x}":"打开练习：{x}","Открыть тренажёр: {x}":"打开对话练习：{x}","Убрать «{q}»":"移除“{q}”","Удалить: {x}":"删除：{x}","Идея на сегодня: {x}.":"今日的建议：{x}。","Идея на сегодня: {x}. Лучше без: {y}.":"今日的建议：{x}。最好避开：{y}。","поесть":"吃饭","побыть":"待一会儿","{0} Б":"{0} B","{0} КБ":"{0} KB","Данные восстановлены ({0}). Обновляю приложение…":"数据已恢复（{0}）。正在刷新应用…","Добавлено записей: {0}":"已添加记录：{0}","тебе обычно подходит — {x}. Выбирай места с учётом этого.":"通常适合你的是——{x}。选地点时可以参考。","тебе обычно подходит — {x}. Лучше без: {y}. Выбирай места с учётом этого.":"通常适合你的是——{x}。最好避开：{y}。选地点时可以参考。","{0} м":"{0} 米","{0} км":"{0} 公里","Убрать из любимых: {x}":"取消收藏：{x}","В любимые: {x}":"加入收藏：{x}","«{q}» добавлено в дневник за сегодня.":"“{q}”已添加到今天的日记。","Ищем места рядом с «{q}»…":"正在搜索“{q}”附近的地点…","Ищем «{q}»…":"正在搜索“{q}”…","Сохранён город «{q}». Выбирай настроение — подборка обновится.":"已保存城市“{q}”。选择心情——推荐会更新。","Найдено практик: {0} из {1}":"找到练习：{0} / {1}","Показать ещё ({0})":"显示更多（{0}）","В диалоге: {x}":"对话中：{x}","Удалить тексты разговоров за {x}? Отметки состояния останутся.":"删除 {x} 的对话文字？状态记录会保留。","Практики: {x}":"练习：{x}","Шаг {0} из {1}":"第 {0} 步，共 {1} 步","Подсказка: {x}":"提示：{x}","Источник: {x}":"来源：{x}","Пройдено стилей: {0} из {1}":"已完成风格：{0} / {1}","День {0}":"第 {0} 天","{x} по дням":"{x}（按天）","Готово: каждый день в {0}:{1}. Пропускать можно — это просто приглашение.":"设置好了：每天 {0}:{1}。跳过也没关系——这只是一个邀请。","Чаще всего тебе помогала практика «{q}» ({0} раз). Это личная заметка, не медицинский вывод.":"最常帮到你的练习是“{q}”（{0} 次）。这只是个人记录，不是医学结论。","Удалить «{q}» из этого дня?":"从这一天中删除“{q}”？","{0} место":"{0} 个地点","{0} места":"{0} 个地点","{0} мест":"{0} 个地点","Играть: {x}":"开始游戏：{x}","{0} мин":"{0} 分钟","{0} минуты":"{0} 分钟","{0} минут":"{0} 分钟","{0} минута":"{0} 分钟","{0}–{1} минут":"{0}–{1} 分钟","рядом":"ryadom","Я":"我","на каждый день":"适合每天","← К играм":"← 返回游戏",". Оценки и популярность в соцсетях появятся только после подключения проверенного источника данных.":"。评分和社交媒体热度只有在接入经过验证的数据源后才会显示。","есть разговор":"有对话","есть отметка состояния":"有状态记录","есть посещённые места":"有去过的地点","Квесты и сюжетные игры пока доступны только на русском языке. Перевод появится в следующих версиях.":"任务和剧情游戏目前只有俄语版本。翻译将在后续版本中推出。","Не знаю, как сказать":"不知道怎么说","Если сейчас очень тяжело":"如果现在非常难熬","С этим не нужно справляться в одиночку. Выбери то, что получится сейчас.":"你不必独自面对。选一件你现在能做到的事。","Позвонить":"打电话","Написать близкому":"给亲近的人发消息","Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь рядом. Помоги мне получить помощь.":"我现在很难受。请给我打电话或陪着我。帮我获得帮助。","Пережить ближайшие минуты":"撑过接下来的几分钟","Медленный выдох длиннее вдоха. Назови пять вещей, которые видишь вокруг. Если рядом есть что-то опасное — отложи это подальше или выйди в другое место.":"慢慢呼气，呼气比吸气长。说出你周围能看到的五样东西。如果身边有危险的东西——把它放远，或者换个地方待。","Дыхание вместе со мной":"跟我一起呼吸","Мой план безопасности":"我的安全计划","Заполни, когда немного спокойнее. План останется только на этом устройстве и откроется здесь в трудную минуту.":"在稍微平静一些时填写。计划只保存在这台设备上，艰难时刻会在这里打开。","Как я понимаю, что мне становится хуже":"我如何察觉自己在变糟","Что помогает мне хоть немного":"什么能让我好受一点","Кому могу написать или позвонить":"我可以联系或打电话给谁","Как сделать обстановку вокруг безопаснее":"如何让周围环境更安全","«Рядом» — не экстренная служба и может не распознать, что тебе плохо. Если есть риск для жизни, звони 112 или обратись к человеку рядом.":"Ryadom 不是紧急服务，可能无法察觉你的状况。如果有生命危险，请拨打 112 或求助身边的人。","Мне очень плохо":"我很难受","Мне сейчас очень плохо — открыть помощь":"我现在很难受——打开求助","Открыть экран помощи":"打开求助页面","Прежде чем продолжить, хочу спросить прямо, потому что это важно: ты сейчас думаешь о том, чтобы причинить себе вред или не жить?":"在继续之前，我想直接问一句，因为这很重要：你现在是否在想伤害自己或不想活下去？","Да":"是","Не знаю":"不知道","Нет, это другое":"不，是别的事","Спасибо за ответ. Продолжим.":"谢谢你的回答。我们继续。","Письмо себе из детства":"写给童年自己的信","Вернуться к ситуации из детства, которая до сих пор отзывается: назвать чувства, признать, что это было, и отпустить.":"回到一段至今仍有回响的童年经历：说出感受，承认它发生过，然后放下。","Бережная практика о детском опыте. Без подробностей — только то, что чувствуется сейчас.":"一个温和的童年经历练习。不需要细节——只关注你现在的感受。","Детский опыт":"童年经历","страх":"害怕","стыд":"羞耻","одиночество":"孤独","обида":"委屈","злость":"愤怒","беспомощность":"无助","вина":"内疚","растерянность":"茫然","горло":"喉咙","грудь":"胸口","живот":"肚子","плечи и шея":"肩膀和脖子","руки":"双手","не чувствую в теле":"身体没有感觉","защиты":"保护","утешения":"安慰","чтобы выслушали":"有人倾听","чтобы объяснили, что происходит":"有人解释发生了什么","чтобы не винили":"不被责怪","чтобы взрослый был рядом":"有大人在身边","чтобы заметили и похвалили":"被看见、被夸奖","права на свои чувства":"拥有自己感受的权利","Это не твоя вина.":"这不是你的错。","Ты имеешь право чувствовать то, что чувствуешь.":"你有权利感受你的感受。","Тебе досталось слишком много для такого возраста.":"对那个年纪来说，你承受得太多了。","Я вижу, как тебе было трудно.":"我看到你那时有多难。","Теперь я рядом и могу о тебе позаботиться.":"现在我在这里，可以照顾你了。","В твоём возрасте никто не справился бы лучше.":"在那个年纪，没有人能做得更好。","Это было.":"这件事发生过。","Это было больно.":"那很痛。","В том возрасте нельзя было сделать больше.":"在那个年纪，不可能做得更多了。","Это закончилось. Сейчас я взрослый человек и я в безопасности.":"这已经结束了。现在我是成年人，我是安全的。","Принять — не значит согласиться, что так было правильно.":"接受不等于认为那是对的。","Практика «Письмо себе из детства»":"练习“写给童年自己的信”","◐ РЯДОМ · ПРАКТИКА":"◐ RYADOM · 练习","Перед началом":"开始之前","← Назад":"← 返回","Мне становится слишком тяжело":"我有点撑不住了","ОСТАНОВКА — ЭТО ТОЖЕ ЗАБОТА":"停下来也是一种照顾","Остановиться — правильное решение":"停下来是正确的决定","Заметить свой предел — важный навык, а не неудача. Вернись в «сейчас»: посмотри вокруг, назови пять предметов, медленно выдохни. Воспоминание никуда не денется — к нему можно вернуться позже, лучше вместе со специалистом.":"察觉自己的极限是一种重要的能力，而不是失败。回到“此刻”：看看四周，说出五样东西，慢慢呼气。这段记忆不会消失——以后可以再回来，最好和专业人士一起。","Если состояние не отпускает или появляются мысли навредить себе — открой экран помощи: там номера, текст для близкого и план безопасности.":"如果状态没有缓解，或出现伤害自己的念头——打开求助页面：那里有电话号码、给亲近之人的话和安全计划。","ПРАКТИКА ЗАВЕРШЕНА":"练习完成","Встреча с собой из прошлого состоялась":"与过去的自己的相遇完成了","Чувства могут отзываться ещё какое-то время — это нормально. Сегодня стоит сделать что-то тёплое и простое для себя: поесть, выйти на воздух, написать близкому человеку.":"这些感受可能还会持续一阵——这很正常。今天为自己做点温暖又简单的事：吃点东西、出去透透气、给亲近的人发个消息。","Оценка не отмечена — это нормально.":"没有评分——没关系。","Напряжение стало немного меньше.":"紧张感减轻了一些。","Напряжение выросло. Позаботься о себе сегодня бережнее и, если это не проходит, обратись к специалисту или близкому.":"紧张感增加了。今天对自己更温柔一些；如果没有缓解，请联系专业人士或亲近的人。","Напряжение не изменилось. Иногда эффект приходит позже — или нужен другой путь.":"紧张感没有变化。有时效果会晚些出现——或者需要换一种方式。","Если это воспоминание часто возвращается, мешает спать, жить, строить отношения — это повод обратиться к психологу или психотерапевту, который работает с травмой. С ним можно пройти этот путь глубже и безопаснее.":"如果这段记忆经常回来，影响睡眠、生活或人际关系——这就是去找擅长创伤治疗的心理咨询师或心理治疗师的理由。在他们的陪伴下，可以更深入、更安全地走这段路。","В дневник сохранены только факт практики и изменение напряжения. Написанное тобой не сохранялось и исчезнет после закрытия.":"日记中只保存了完成练习这件事和紧张程度的变化。你写下的内容没有保存，关闭后就会消失。","Бережно, в своём темпе":"温和地，按自己的节奏","Мы вернёмся к ситуации из детства, которая до сих пор отзывается. Подробности вспоминать не нужно — важно то, что ты чувствуешь сейчас. Остановиться можно в любой момент.":"我们会回到一段至今仍有回响的童年经历。不需要回忆细节——重要的是你现在的感受。随时可以停下。","С каким воспоминанием хочется побыть?":"你想和哪段记忆待一会儿？","Задевает, но с ним можно побыть 10 минут":"会触动我，但我能和它待10分钟","Очень тяжёлое: насилие, сильный страх, то, что накрывает":"非常沉重：暴力、强烈的恐惧、会把我淹没的事","С очень тяжёлыми воспоминаниями самостоятельно лучше не работать: они могут накрыть сильнее, чем кажется. Эта практика подходит для чего-то полегче. С тяжёлым опытом бережнее и безопаснее идти к специалисту по травме. Можно выбрать другое, менее тяжёлое воспоминание — или просто закрыть практику.":"非常沉重的记忆最好不要独自处理：它们可能比想象中更容易把你淹没。这个练习适合较轻的经历。面对沉重的经历，找创伤方面的专业人士会更温和、更安全。你可以选一段不那么沉重的记忆——或者直接关闭练习。","Насколько тебе неспокойно прямо сейчас?":"你现在有多不安？","0 — спокойно":"0 — 平静","10 — очень тяжело":"10 — 非常难受","Сейчас напряжение очень высокое. Лучше сначала успокоиться: дыхание, прогулка, разговор с близким. К практике можно вернуться в другой день.":"现在的紧张程度很高。最好先平静下来：呼吸、散步、和亲近的人聊聊。可以改天再来做这个练习。","Если ты сейчас в опасности или ситуация из прошлого продолжается — сначала позаботься о безопасности: кнопка «Мне очень плохо» вверху экрана.":"如果你现在有危险，或过去的情况仍在继续——先照顾好自己的安全：屏幕顶部的“我很难受”按钮。","01 · ОПОРА":"01 · 支撑","Сначала — здесь и сейчас":"先回到此时此地","Прежде чем идти в прошлое, найдём опору в настоящем. Посмотри вокруг и назови про себя три предмета. Почувствуй, как ты сидишь, как стопы касаются пола.":"在回到过去之前，先在当下找到支撑。看看四周，在心里说出三样东西。感受你怎样坐着，双脚怎样踩着地面。","вдох 4 · выдох 6":"吸气4 · 呼气6","Сделай три медленных выдоха — длиннее вдоха. Вспомни место, человека или вещь, рядом с которыми тебе спокойно. Это твоя опора: к ней можно вернуться в любой момент практики.":"慢慢呼气三次——呼气比吸气长。想一个让你感到平静的地方、人或物。这是你的支撑：练习中随时可以回到这里。","Опора есть →":"我找到支撑了 →","02 · ТА СИТУАЦИЯ":"02 · 那段经历","Одной строкой, без подробностей":"一句话，不讲细节","Сколько тебе было лет и что происходило — коротко, как заголовок. Не нужно пересказывать и прокручивать сцену. Можно ничего не писать, а просто держать её в уме.":"你当时几岁、发生了什么——简短地，像一个标题。不必复述或回放那个场景。也可以什么都不写，只在心里想着。","Мне было примерно… (необязательно)":"我那时大约……（可选）","Например: «Мне 8, родители ругаются, а я сижу в своей комнате»":"例如：“我8岁，爸妈在吵架，我坐在自己的房间里”","Текст остаётся только на этом экране и не сохраняется.":"文字只留在这个屏幕上，不会保存。","03 · ЧУВСТВА":"03 · 感受","Какие чувства были тогда?":"那时有哪些感受？","Отметь всё, что откликается. Чувства не бывают «неправильными» — тогда у них были причины.":"选出所有有共鸣的。感受没有“对错”——那时它们都有原因。","Где это отзывается в теле сейчас?":"现在它在身体的哪里有反应？","Тогда ребёнок чувствовал: {x}. Эти чувства были естественной реакцией на то, что происходило.":"那时，孩子感受到的是：{x}。这些感受是对当时发生的事的自然反应。","Насколько тяжело сейчас?":"现在有多难受？","Напряжение сильно выросло. Сейчас лучше остановиться и вернуться к опоре. Это правильное решение, а не слабость.":"紧张感上升了很多。现在最好停下来，回到你的支撑。这是正确的决定，不是软弱。","Остановиться и вернуться к опоре":"停下来，回到支撑","04 · ЧЕГО НЕ ХВАТАЛО":"04 · 缺少了什么","Что тогда было нужно?":"那时需要的是什么？","Каждому ребёнку нужны безопасность, утешение и взрослый рядом. Что было нужно тебе в той ситуации?":"每个孩子都需要安全、安慰和身边有大人。在那个情境里，你需要的是什么？","Тебе тогда были нужны: {x}. Это нормальные потребности. То, что их не было, — не твоя вина: заботиться о ребёнке должны взрослые.":"那时你需要的是：{x}。这些都是正常的需要。没有得到它们不是你的错：照顾孩子是大人的责任。","05 · ПРИЗНАТЬ":"05 · 承认","Это было":"这件事发生过","Принятие — не значит согласиться, что так было правильно, и не значит простить. Это значит перестать спорить с тем, что уже случилось, и забрать силы обратно в настоящее. Прочитай медленно, можно вслух:":"接受不等于认为那是对的，也不等于原谅。它意味着不再和已经发生的事较劲，把力量收回到当下。慢慢读，可以读出声：","Какая фраза отозвалась сильнее? Побудь с ней пару вдохов.":"哪句话最触动你？和它待上几次呼吸。","06 · СЛОВА СЕБЕ ТОГДА":"06 · 对那时的自己说的话","Что ты скажешь тому ребёнку?":"你会对那个孩子说什么？","Представь себя в том возрасте. Сейчас ты взрослый человек и можешь сказать то, чего тогда никто не сказал. Выбери фразы или напиши своё письмо.":"想象那个年纪的自己。现在你是大人了，可以说出当时没人说过的话。选几句话，或写下你自己的信。","Моё письмо себе в детстве (необязательно)":"我写给童年自己的信（可选）","Привет. Я — это ты через много лет. Вот что мне хочется тебе сказать…":"你好。我是很多年后的你。我想对你说……","ТВОИ СЛОВА":"你的话","Письмо никуда не отправляется и не сохраняется.":"这封信不会发送，也不会保存。","07 · ОТПУСТИТЬ":"07 · 放下","Как ты хочешь завершить?":"你想怎样结束？","Отпустить — не значит забыть. Это значит перестать носить это с собой каждый день. Выбери, что подходит сейчас.":"放下不等于忘记。它意味着不再每天背着它走。选一个现在适合你的方式。","Отпустить с выдохом":"随着呼气放下","Три медленных выдоха. С каждым представь, что тяжесть выходит из тела.":"慢慢呼气三次。每一次都想象沉重感离开身体。","Убрать в контейнер":"放进容器里","Представь прочную коробку. Положи туда это воспоминание и закрой. Оно будет там, пока ты не решишь вернуться к нему — например, со специалистом.":"想象一个坚固的盒子。把这段记忆放进去，盖上。它会一直在那里，直到你决定回来面对它——比如和专业人士一起。","Стереть написанное":"擦掉写下的内容","Если письмо написано — сотри его. Слова уже сказаны, им не нужно оставаться на экране.":"如果写了信——把它擦掉。话已经说出口了，不需要留在屏幕上。","Коробка закрыта. Только тебе решать, когда её открыть.":"盒子已经盖上。什么时候打开，只由你决定。","Написанное стёрто. То, что важно, осталось с тобой.":"写下的内容已经擦掉。重要的东西留在了你心里。","Сделай выдох длиннее вдоха. И ещё раз. И ещё.":"呼气比吸气长一些。再来一次。再一次。","Насколько неспокойно сейчас?":"你现在有多不安？","Завершить":"完成"},"lex":{"emo":{"fear":["焦虑","担心","害怕","紧张","恐慌","不安","压力"],"sad":["难过","伤心","哭","抑郁","沮丧","悲伤","郁闷"],"anger":["生气","愤怒","气死","烦","恼火","讨厌","恨"],"tired":["累","疲惫","没力气","没精神","精疲力尽","困","倦"],"lonely":["孤单","孤独","一个人","没人","寂寞"],"hurt":["委屈","受伤","伤害","背叛","侮辱","羞辱"],"shame":["羞愧","内疚","丢脸","惭愧","自责"],"good":["很好","不错","开心","高兴","快乐","平静","好多了"]},"theme":{"work":["工作","上班","老板","领导","同事","公司"],"family":["家人","家里","妈妈","爸爸","父母","母亲","父亲","哥哥","姐姐","弟弟","妹妹","孩子"],"love":["男朋友","女朋友","老公","老婆","对象","恋爱","分手","感情"],"friends":["朋友"],"health":["健康","生病","病","疼","医生","医院"],"money":["钱","债","工资","房租","贷款"],"study":["学校","考试","学习","大学","上课","老师","作业"]},"intent":{"bye":["再见","拜拜","晚安"],"thanks":["谢谢","多谢","感谢"],"doctor":["你是医生","心理医生","咨询师"],"who":["你是谁","你是人吗","机器人"],"hello":["你好","嗨","哈喽","您好"],"help":["帮帮我","怎么办"],"go":["去哪","出去","吃什么"],"nowant":["不想","别管我","不要"]}},"help":{"lines":["中国：心理援助热线 12356"]}};
